{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello आपको ice making machine की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "ठीक है मैं Tanya बोल रही हूं IndiaMART से।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "हमारे पास कई अच्छे sellers available हैं जिनसे मैं अभी आपको connect करवाऊंगी।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "बस कुछ details confirm कर दीजिए।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "चलिए अब production capacity के बारे में बात कर लेते हैं।"
    },
    {
      "i": 6,
      "speaker": "bot",
      "text": "आपको 1 ton day चाहिए या कुछ और?"
    },
    {
      "i": 7,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 8,
      "speaker": "caller",
      "text": "और वही से ice cream का जो"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "Sorry आपकी आवाज़ clear नहीं आई ज़रा दोबारा बताइए।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "आपको production capacity में क्या prefer करेंगे?"
    },
    {
      "i": 11,
      "speaker": "caller",
      "text": "आए।"
    },
    {
      "i": 12,
      "speaker": "caller",
      "text": "वो ice cream का?"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "समझ गई।"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "क्या आपको ice making machine ही चाहिए या आप ice cream machine की बात कर रहे हैं?"
    },
    {
      "i": 15,
      "speaker": "caller",
      "text": "हाँ खाली ice cream machine चाहिए।"
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "आपको जो ice cream बनाने वाली ice cream machine चाहिए ना?"
    },
    {
      "i": 17,
      "speaker": "caller",
      "text": "पूछो।"
    },
    {
      "i": 18,
      "speaker": "caller",
      "text": "हाँ जो इसमें बनता है ना जो पानी देखो जो चक्का घोरता है ना वो वाला।"
    },
    {
      "i": 19,
      "speaker": "bot",
      "text": "ठीक है?"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "अब production capacity के बारे में बात कर लेते हैं।"
    },
    {
      "i": 21,
      "speaker": "bot",
      "text": "आपको 10 liters या 5 liters चाहिए या कुछ और?"
    },
    {
      "i": 22,
      "speaker": "caller",
      "text": "पूछते।"
    },
    {
      "i": 23,
      "speaker": "caller",
      "text": "तो डेढ़ लीटर वाला कितना है और पाँच लीटर वाला कितना है?"
    },
    {
      "i": 24,
      "speaker": "bot",
      "text": "आप price की बात कर रहे हैं तो ये आप seller से discuss कर सकते हैं वो आपको best rates देंगे।"
    },
    {
      "i": 25,
      "speaker": "bot",
      "text": "अभी आप बताइए कि आपको कितनी capacity चाहिए?"
    },
    {
      "i": 26,
      "speaker": "caller",
      "text": "तो कितना का वो चलता है चार inch में चलता है ना इसमें चलता है?"
    },
    {
      "i": 27,
      "speaker": "bot",
      "text": "मैं समझ नहीं पाई please एक बार फिर से बता दीजिए कि आपको कितनी capacity चाहिए या फिर आप seller से इसके बारे में बात कर सकते हैं?"
    },
    {
      "i": 28,
      "speaker": "caller",
      "text": "हाँ बात कह रहे आपको वो जो machine ice cream वाला machine चलता है तो उसमें sale है क्या?"
    },
    {
      "i": 29,
      "speaker": "bot",
      "text": "seller के पास ये product available है।"
    }
  ]
}
